// GENERATED by `cargo run -p deck-space --features schema --bin deck-schema` from deck/catalog (the kind catalog) – do not edit.
// The kind catalog (`Catalog`, `Descriptor`, …) and the rig bundle documents (`Bundle`, `Instrument`, `Preset`, …).

export type AnyChannels = "any";

/** a read-only data slot of a module; a node binds an asset id to it, the host fills it at instantiation (ABI-V2 §1.5) */
export type AssetDesc = {
	doc?: string;
	kind: AssetKind;
	/** the largest asset the slot takes, in bytes (decoded) */
	max_bytes: number;
	name: string;
};

/** what an asset slot holds once the host has filled it: planar f32 PCM, raw bytes, or a small RGBA8 image (ABI-V2 §1.5) */
export type AssetKind = "pcm" | "bytes" | "image";

export type Bundle = {
	instrument?: Instrument[];
	/** the modules it plays: a code rig's policy (#408), a track's module (#430) – the `module:<id>` documents' descriptors */
	module?: Descriptor[];
	preset?: Preset[];
	rig: Rig;
};

/** The catalog as a document: `kinds.json`. The API merges the published modules' descriptors into `kinds`. */
export type Catalog = {
	catalog_version: number;
	kinds: Descriptor[];
};

/** an audio port's channel count; `any` = whatever the cable carries (§2.6) */
export type Channels = number | AnyChannels;

export type Curve = "lin" | "log";

/** One node kind or module: what the engine, the validator, the editor and the agents all read. */
export type Descriptor = {
	/** modules only: the ABI version they speak */
	abi?: number | null;
	/** read-only data slots (samples, sequences, images) the host fills at instantiation */
	assets?: AssetDesc[];
	/** the batch evaluator (deck-core batch.rs, live-core, the browser) can run it */
	batch?: boolean;
	doc?: string;
	domain?: Domain;
	/** the stage's cargo feature that carries the kind (`core` = always); empty = none */
	feature?: string;
	/** the kind follows the transport by default (#359: stops, holds, resumes with it); a node's `follow_transport` overrides it */
	follow_transport?: boolean;
	/** constant latency in frames, for the engine's compensation (ENGINE-REFACTOR-PLAN §2.6a) */
	latency?: number;
	/** deck-core's module for the kind (control · synth · analysis · stage · 3d …); empty = none */
	module?: string;
	/** modules only (A1, #409): the moods the module knows, in its own order – the deck hands a module the mood's place here + 1 as `mood_index` (0 = a mood not in the list; deck-space context.rs) */
	moods?: string[];
	name: string;
	/** capabilities the kind needs (#312): without one it does not run */
	needs?: string[];
	params?: ParamDesc[];
	ports?: PortDesc[];
	/** the kind's one factory preset */
	preset?: FactoryPreset | null;
	/** the show's variable slots the kind may read (`story.act` …, ABI-V2 §3) */
	reads?: string[];
	/** a scene owns it once: never inside an instrument */
	scene_only?: boolean;
	scope?: Scope;
	version?: string;
	/** capabilities the kind uses when they are there (#312): without one it runs on, the sensor reads "absent" */
	wants?: string[];
};

export type Dir = "in" | "out";

export type Domain = "audio" | "control" | "video";

/** A shown parameter: a control input `node.port`, its label, and a narrower range than params.rs's (optional). */
export type Expose = {
	label?: { [key: string]: string };
	path: string;
	range?: number[] | null;
};

/** a module's one factory preset (ABI-V2 §2); every other preset is a DB document (deck-space's rig `Preset`) */
export type FactoryPreset = {
	doc?: string;
	name: string;
	/** parameter name → value; a parameter not named keeps its default */
	values?: { [key: string]: number };
};

export type Instrument = {
	/** the parameters it shows; empty = every control input */
	expose?: Expose[];
	id: string;
	kind: InstrumentKind;
	link?: LinkDef[];
	name?: { [key: string]: string };
	node: NodeDef[];
	/** the track's output: an audio output `node.port` (a bare node = its `out`). None (#430): a silent track – a note source (a step sequencer, a world node) with no strip and no outlet, wired by event cables */
	out?: string | null;
	rights?: Rights;
};

/** What an instrument is for – an Ableton track's role. A scene object's sound (#210) is an instrument too. */
export type InstrumentKind = "drum" | "bass" | "lead" | "pad" | "voice" | "sampler" | "texture" | "fx";

export type LinkDef = {
	from: string;
	/** an audio link's channel map (plan 2.6, #318): `[source, target]` pairs counted from 1 – `[[1, 3], [2, 4]]` lands a stereo source on channels 3 and 4 (a send's offset); one source may go to several targets, several sources into one target sum. Empty = channel n to channel n. `scale` on an audio link is the send level. */
	map?: number[][];
	offset?: number;
	scale?: number;
	to: string;
};

/** A control source bound to a parameter. `source`: `midi:<channel>:cc:<n>` · `face:<blendshape>` (`face:jawOpen`) · `motion:<axis>` (`motion:tilt.x`) · `pad:<control>` (`pad:left.x`) · `stick:<left|right>.<x|y>`; its 0..1 (or −1..1) lands on `target` across `range` (default: the parameter's range, params.rs). */
export type Mapping = {
	range?: number[] | null;
	source: string;
	target: string;
};

/** how a control output with a `path` acts on its target (ABI-V2 §1.2, §5): replace it, add to it, scale it */
export type Mode = "set" | "add" | "mul";

export type NodeDef = {
	id: string;
	kind: string;
	[key: string]: unknown;
};

export type ParamDesc = {
	/** a string parameter's values (`osc.wave`); min / max / default are then unused */
	choices?: string[];
	curve?: Curve;
	/** None = not driven until a param or a link sets it (an `events` node's knobs: the patch's own values play) */
	default?: number | null;
	doc?: string;
	max?: number;
	min?: number;
	name: string;
	/** the value is also an input port of this name (a control input is both) */
	port?: boolean;
	/** Hz, s, dB, ratio, px … */
	unit?: string;
};

/** A rig's policy: the module that drives its tracks, the node's seed and its parameters' values. */
export type Policy = {
	/** the `module:<id>` document's id – its descriptor's name */
	module: string;
	/** the node's seed (the module seed rule: 1 unless set) */
	seed?: number | null;
	/** its parameters' values by name (the rest keep their defaults); persona / mood values `policy:<param>` go on top */
	values?: { [key: string]: number };
};

export type PortDesc = {
	/** event ports: records per block (1 … `MAX_EVENT_CAPACITY`) */
	capacity?: number;
	/** audio ports: how many channels the port carries */
	channels?: Channels | null;
	/** control outputs: the value is an index into these names (an enum) */
	choices?: string[];
	dir: Dir;
	doc?: string;
	/** false = deck-core's control graph (its `KindInfo`) does not take this input, e.g. the `cv` of `osc` */
	engine?: boolean;
	/** control outputs with a `path`: how the value acts on the target */
	mode?: Mode;
	name: string;
	/** event ports: the deck-events names it emits / accepts (`music.note`, `story.act` …); interned once at load */
	names?: string[];
	/** control outputs: the target it writes (a group child's parameter, preset, gain …, ABI-V2 §5); empty = a graph cable */
	path?: string;
	/** event ports: the positional meaning of the prop slots (at most `MAX_EVENT_PROPS`) */
	props?: string[];
	/** audio inputs: a second input fed by sends, not by the graph's sum (ENGINE-REFACTOR-PLAN §2.6) */
	sidechain?: boolean;
	/** ABI v1 module descriptors call it `kind` */
	type: PortType;
};

/** a port's type; a link joins ports of one type (`cv` = pitch / gate carried in an audio port, see `seq`) */
export type PortType = "audio" | "control" | "cv" | "video" | "event";

export type Preset = {
	id: string;
	instrument: string;
	/** links added; one into an input that already has a link replaces it */
	link?: LinkDef[];
	/** control sources bound to parameters (#209, #212), saved with the preset */
	mapping?: Mapping[];
	name?: { [key: string]: string };
	/** the preset this one derives from (same instrument); none = a root */
	parent?: string | null;
	rights?: Rights;
	/** free tags: a character's trait, a mood, a persona, a genre … */
	tags?: string[];
	/** inputs whose link is removed (`node.port`) */
	unlink?: string[];
	/** control input `node.port` → its value */
	values?: { [key: string]: number };
};

/** A character's (or object's) set of tracks. */
export type Rig = {
	/** mood (the `moods` registry's ids) → overrides (applied after the persona's) */
	moods?: { [key: string]: Variant };
	/** persona → overrides (applied first) */
	personas?: { [key: string]: Variant };
	/** a code rig (#408): the control module that drives the tracks (policy.rs); none = the tables alone */
	policy?: Policy | null;
	rights?: Rights;
	/** sends and modulation between tracks, and to the being's look (`being:hue`) – everything is audiovisual */
	route?: Route[];
	/** the two corner sticks of the phone deck, `[[x, y], [x, y]]` (left, right) as knob paths (`<track>_<node>.<port>`); none = the first four knobs (#191) */
	sticks?: string[][] | null;
	/** whose rig: `character.<id>` (`character.<id>.<persona>` for a persona's own) or `item.<id>` – KANON's subjects */
	subject: string;
	track: Track[];
};

/** What a holder may do (owner 2026-10-30: "the definition says who may save, copy or change it"). */
export type Right = "play" | "tweak" | "derive" | "copy";

/** Rights per way of holding, carried by every definition. Default: lent = play + tweak, core = + derive, owned = all. */
export type Rights = {
	core?: Right[];
	lent?: Right[];
	owned?: Right[];
};

/** `from` / `to` are `<track>:<node>.<port>`; `to` may be `being:<input>` (the space node's hue, glow, light, pulse). Every sounding track reaches the master through its mixer strip; an audio route is a send into another track's audio input (an fx track; `scale` = its level), a control route a modulation, an event route an event cable (#430: many to many, a note source's silent track to a synth's track). */
export type Route = {
	from: string;
	offset?: number;
	scale?: number;
	to: string;
};

/** where a kind stands: usable in a scene / instrument graph, a helper only the batch evaluator runs, or planned */
export type Scope = "graph" | "internal" | "planned";

/** One track: an instrument, its default preset, its mixer strip. */
export type Track = {
	gain?: number;
	id: string;
	instrument: string;
	mute?: boolean;
	/** −1 left … 1 right */
	pan?: number;
	preset?: string | null;
};

/** A persona's or a mood's overrides: another preset per track, and single values (`<track>:<node>.<port>`). */
export type Variant = {
	presets?: { [key: string]: string };
	values?: { [key: string]: number };
};

